import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 505;
    static int n, m, mod;
    static int[] jc = new int[MAXN * 4];
    static int[] inv = new int[MAXN * 4];

    static int upd(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add(int[] x, int y) {
        for (int i = 0; i < x.length; i++) {
            x[i] = upd(x[i] + y);
        }
    }

    static int ksm(int x, int k) {
        int ans = 1;
        int base = x % mod;
        while (k > 0) {
            if ((k & 1) == 1) {
                ans = (int) ((long) ans * base % mod);
            }
            base = (int) ((long) base * base % mod);
            k >>= 1;
        }
        return ans;
    }

    static void init(int n) {
        jc[0] = 1;
        for (int i = 1; i <= n; i++) {
            jc[i] = (int) ((long) jc[i - 1] * i % mod);
        }
        inv[n] = ksm(jc[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
        }
    }

    static int C(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int) ((long) jc[n] * inv[n - m] % mod * inv[m] % mod);
    }

    static int S(int n) {
        return n * (n + 1) / 2;
    }

    static List<Integer> multiply(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
        for (int i = 0; i < sizeA; i++) {
            for (int j = 0; j < sizeB; j++) {
                int val = (int) ((long) A.get(i) * B.get(j) % mod);
                C.set(i + j, upd(C.get(i + j) + val));
            }
        }
        return C;
    }

    static int G(int n, int m) {
        return C(m + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m = Integer.parseInt(st.nextToken());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        init(m << 1);

        List<Integer> f = new ArrayList<>(Collections.nCopies(n + 1, 0));
        List<Integer> g = new ArrayList<>(Collections.nCopies(n + 1, 0));
        f.set(0, 1);

        for (int i = 1; i <= n; i++) {
            int sum = 0;
            for (int j = 0; j < i; j++) {
                int val = (int) ((long) f.get(j) * f.get(i - 1 - j) % mod);
                val = (int) ((long) val * C(i - 1, j) % mod);
                sum = upd(sum + val);
            }
            sum = (int) ((long) sum * (i + 1) % mod);
            f.set(i, sum);
        }

        for (int i = 1; i <= n; i++) {
            int sum = 0;
            for (int j = 0; j < i; j++) {
                int term1 = (2L * f.get(j) * g.get(i - 1 - j) % mod) * C(i - 1, j) % mod;
                term1 = (int) (term1 * (i + 1) % mod);
                int term2 = (int) ((long) C(i - 1, j) * (S(j) + S(i - 1 - j)) % mod);
                term2 = (int) ((long) term2 * f.get(j) % mod * f.get(i - 1 - j) % mod);
                sum = upd(sum + (term1 + term2) % mod);
            }
            g.set(i, sum);
        }

        for (int i = 0; i <= n; i++) {
            g.set(i, (int) ((long) g.get(i) * inv[i] % mod));
            f.set(i, (int) ((long) f.get(i) * inv[i] % mod));
        }

        int ans = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int val = (int) ((long) g.get(n) * G(i + 1, m - n - i + 1) % mod);
            val = (int) ((long) val * jc[n] % mod);
            val = (int) ((long) val * i % mod);
            ans = upd(ans + val);
            // g = g * f
            g = multiply(g, f);
            g = g.subList(0, n + 1);
        }

        System.out.println(ans);
    }
}

